// Process 699 Purchase Orders from API bridge
const httpResponse = $json;
const allPOs = httpResponse.data || [];

// Create lookup map for fast access
const poMap = {};
allPOs.forEach(po => {
  poMap[po.po_number] = {
    number: po.po_number,
    amount: parseFloat(po.total_amount) || 0,
    spent: parseFloat(po.spent_amount) || 0,
    currency: po.currency,
    status: po.status,
    valid_from: po.valid_from,
    valid_until: po.valid_until,
    remaining: (parseFloat(po.total_amount) || 0) - (parseFloat(po.spent_amount) || 0)
  };
});

// Status summary
const statusCount = {
  active: allPOs.filter(p => p.status === 'active').length,
  expiring_soon: allPOs.filter(p => p.status === 'expiring_soon').length,
  low_balance: allPOs.filter(p => p.status === 'low_balance').length,
  fully_utilized: allPOs.filter(p => p.status === 'fully_utilized').length
};

// Currency summary
const currencies = [...new Set(allPOs.map(p => p.currency))];
const currencyTotals = {};
allPOs.forEach(po => {
  const curr = po.currency || 'USD';
  const amt = parseFloat(po.total_amount) || 0;
  currencyTotals[curr] = (currencyTotals[curr] || 0) + amt;
});

return [{
  json: {
    summary: {
      total_po_count: allPOs.length,
      status_breakdown: statusCount,
      currencies: currencies.length,
      currency_list: currencies,
      total_value_usd: currencyTotals.USD || 0,
      timestamp: new Date().toISOString()
    },
    po_lookup: poMap,
    all_pos: allPOs,
    first_5: allPOs.slice(0, 5)
  }
}];

// ==========================================
// MERGE AI OUTPUT + EXCEL + PO DATA
// Processes ALL items from multiplexed input
// ==========================================

// 1. GET DATA from multiplexed Merge node
const item = $input.item.json;
const aiAgentOutput = item.output || '';

// 2. PARSE JSON FROM AI OUTPUT
let parsedAI = {};
try {
  const jsonMatch = aiAgentOutput.match(/```json\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    parsedAI = JSON.parse(jsonMatch[1]);
  } else if (aiAgentOutput) {
    parsedAI = JSON.parse(aiAgentOutput);
  }
} catch (e) {
  parsedAI = {};
}

// 3. GET MATCHING EXCEL ROW
const allExcelRows = $('EXCEL PARSER').all();
const originalData = allExcelRows[$itemIndex]?.json || allExcelRows[0]?.json || {};

// 4. GET PO LOOKUP DATA from multiplexed PO data
const poLookup = item.po_lookup || {};

// 5. MATCH PO by Vendor PO field from Excel
const vendorPO = originalData["Vendor PO"] || "";
const matchedPO = poLookup[vendorPO] || null;

// 6. CONVERT TIME SPENT TO DECIMAL HOURS
const timeSpent = originalData["Time Spent"] || "00:00:00";
const [hours, minutes, seconds] = timeSpent.split(":").map(Number);
const workHoursFromTime = hours + minutes / 60 + seconds / 3600;
const workHoursDecimal = parsedAI.work_hours || workHoursFromTime;

// 7. RETURN MERGED DATA
return {
  json: {
    request_id: originalData["Request ID"],
    subject: originalData["Subject"],
    site: originalData["Site"],
    technician: originalData["Assigned Technician"],
    status: originalData["Request Status"],
    account: originalData["Account"],
    comments: originalData["Comments"],
    country: parsedAI.country || originalData["COUNTRY"] || "",
    city: parsedAI.city || originalData["CITY OR TOWN"] || "",
    eta_dates: parsedAI.eta_dates || [],
    priority: parsedAI.priority || originalData["Priority"] || "",
    ticket_number: parsedAI.ticket_number || "",
    technician_name: parsedAI.technician_name || originalData["Assigned Technician"] || "",
    time_spent_raw: timeSpent,
    work_hours: Number(workHoursDecimal.toFixed(3)),
    excel_hourly_cost: parseFloat(originalData["Hourly cost"]) || 0,
    excel_revenue_rate: parseFloat(originalData["Revenue rate"]) || 0,
    excel_first_hour_rate: parseFloat(originalData["1st Hour Revenue Rate"]) || 0,
    excel_total_revenue: parseFloat(originalData["Total Revenue"]) || 0,
    excel_total_labor_cost: parseFloat(originalData["Total labor Cost"]) || 0,
    excel_currency: originalData["currency-cost"] || "GBP",
    excel_ooh_cost: parseFloat(originalData["OOH Cost"]) || 0,
    vendor_po: vendorPO,
    po_number: matchedPO ? matchedPO.number : "NOT_FOUND",
    po_remaining_balance: matchedPO ? matchedPO.remaining : 0,
    po_total_amount: matchedPO ? matchedPO.amount : 0,
    po_spent_amount: matchedPO ? matchedPO.spent : 0,
    po_status: matchedPO ? matchedPO.status : "unverified",
    po_currency: matchedPO ? matchedPO.currency : "",
    region: originalData["REGION OF THE COUNTRY"] || "",
    customer_reference: originalData["CUSTOMER REFERENCE"] || "",
    external_po: originalData["External PO NUMBER"] || "",
    processed_at: new Date().toISOString(),
    ai_source: "claude-sonnet-4.5",
    item_index: $itemIndex
  }
};

// ==========================================
// FETCH RATE CARD - Uses Excel rate data
// ==========================================

const data = $input.item.json;

const hourlyRate = data.excel_hourly_cost || 0;
const revenueRate = data.excel_revenue_rate || 0;
const currency = data.excel_currency || "GBP";

let rateSource = "default_fallback";
let effectiveRate = 45.50;

if (hourlyRate > 0) {
  effectiveRate = hourlyRate;
  rateSource = "excel_hourly_cost";
} else if (revenueRate > 0) {
  effectiveRate = revenueRate;
  rateSource = "excel_revenue_rate";
}

return {
  json: {
    ...data,
    rate_card: {
      hourly_cost: effectiveRate,
      revenue_rate: revenueRate,
      first_hour_rate: data.excel_first_hour_rate,
      ooh_cost: data.excel_ooh_cost,
      total_labor_cost: data.excel_total_labor_cost,
      currency: currency,
      source: rateSource
    },
    rate_match_type: rateSource !== "default_fallback" ? "excel_exact" : "default_fallback"
  }
};

// ==========================================
// CALCULATE FINAL BILLING AMOUNT
// Uses Excel rates + PO balance validation
// ==========================================

const data = $input.item.json;
const rateCard = data.rate_card || {};
const workHours = data.work_hours || 0;

const hourlyRate = rateCard.hourly_cost || 45.50;
const currency = rateCard.currency || "GBP";

const calculatedAmount = workHours * hourlyRate;
const finalAmount = Math.round(calculatedAmount * 100) / 100;

const poRemaining = data.po_remaining_balance || 0;
const poStatus = data.po_status || "unverified";
const hasValidPO = poStatus !== "unverified" && poStatus !== "NOT_FOUND";
const overBudget = hasValidPO && finalAmount > poRemaining;

const excelRevenue = data.excel_total_revenue || 0;
const revenueDeviation = excelRevenue > 0
  ? ((finalAmount - excelRevenue) / excelRevenue) * 100
  : 0;
const revenueAnomaly = Math.abs(revenueDeviation) > 10;

return {
  json: {
    request_id: data.request_id,
    ticket_number: data.ticket_number,
    country: data.country,
    city: data.city,
    site: data.site,
    technician: data.technician_name,
    account: data.account,
    priority: data.priority,
    work_hours: workHours,
    hourly_rate: Number(hourlyRate.toFixed(2)),
    currency: currency,
    final_amount: finalAmount,
    excel_total_revenue: excelRevenue,
    revenue_deviation_percent: Number(revenueDeviation.toFixed(2)),
    revenue_anomaly: revenueAnomaly,
    vendor_po: data.vendor_po,
    po_status: poStatus,
    po_remaining_balance: poRemaining,
    over_budget: overBudget,
    budget_warning: overBudget
      ? `Amount ${finalAmount} exceeds PO remaining ${poRemaining}`
      : null,
    rate_source: rateCard.source || "unknown",
    rate_match_type: data.rate_match_type,
    calculated_at: new Date().toISOString(),
    billing_step: "8/8 Complete",
    item_index: data.item_index
  }
};
